<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigSessionSsoTtlSecondsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigSessionSsoTtlSecondsAccessor trait.
 *
 * Covers null default, string/VO assignment via withSessionSsoTtlSeconds,
 * getSessionSsoTtlSeconds/sessionSsoTtlSeconds accessors, and isSessionSsoTtlSecondsChanged with/without original.
 */
class TenantConfigSessionSsoTtlSecondsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSessionSsoTtlSeconds creates a new instance with the SessionSsoTtlSeconds set
     * from a string value, and getSessionSsoTtlSeconds returns the primitive string.
     */
    public function testWithSessionSsoTtlSecondsFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigSessionSsoTtlSecondsAccessorUnitTest();

        // Act
        $result = $holder->withSessionSsoTtlSeconds(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getSessionSsoTtlSeconds());
    }
    /**
     * Asserts that withsessionSsoTtlSeconds has access to the value object
     * from a string value, and getSessionSsoTtlSeconds returns the primitive string.
     */
    public function testWithSessionSsoTtlSecondsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigSessionSsoTtlSecondsAccessorUnitTest();

        // Act
        $result = $holder->withSessionSsoTtlSeconds(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->sessionSsoTtlSeconds()->value());
    }
    public function testChangedSessionSsoTtlSeconds(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigSessionSsoTtlSecondsAccessorUnitTest()->withSessionSsoTtlSeconds(1);
        $original = $holder->withSessionSsoTtlSeconds(1);
        $same = $holder->withSessionSsoTtlSeconds(1);
        $modified = $holder->withSessionSsoTtlSeconds(2);

        // Act
        $withSame = $original->isSessionSsoTtlSecondsChanged($same);
        $withDiferent = $original->isSessionSsoTtlSecondsChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigSessionSsoTtlSecondsAccessorUnitTest
{
    use TenantConfigSessionSsoTtlSecondsAccessor;
}
